insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Viandes, os et graisses', 'Les viandes, les os et les graisses vont au bac brun. Les graisses en petites quantites, absorbees dans du papier ou du carton.', null, null), (@id, 'en', 'Meat, bones and fat', 'Meat, bones and fat go in the brown bin. Fat in small amounts, soaked up in paper or cardboard.', null, null), (@id, 'zh', '肉类、骨头和油脂', '肉类、骨头和油脂放入棕桶。油脂请少量，并用纸或纸板吸附。', null, null);
