insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'The, tisane et cafe', 'Les residus de the, de tisane et de cafe vont au bac brun, avec les filtres a cafe en papier.', null, null), (@id, 'en', 'Tea, herbal tea and coffee', 'Tea, herbal tea and coffee grounds go in the brown bin, with paper coffee filters.', null, null), (@id, 'zh', '茶叶、花草茶和咖啡渣', '茶叶、花草茶和咖啡渣放入棕桶，纸质咖啡滤纸也一样。', null, null);
