insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Mouchoirs et essuie-tout', 'Les mouchoirs et l''essuie-tout vont au bac brun, sauf s''ils sont souilles d''un produit nettoyant nocif: alors a la poubelle.', null, null), (@id, 'en', 'Tissues and paper towels', 'Tissues and paper towels go in the brown bin, unless soiled with a harmful cleaning product: then the garbage.', null, null), (@id, 'zh', '纸巾和厨房纸', '纸巾和厨房纸放入棕桶；若沾有有害清洁剂，则放入垃圾桶。', null, null);
