insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Papiers et cartons souilles d aliments', 'Les papiers et cartons souilles par la nourriture vont au bac brun: boites de pizza, sacs de frites, papiers de muffins, papier parchemin. S''ils sont cires, plastifies ou lamines, c''est la poubelle.', null, null), (@id, 'en', 'Food-soiled paper and cardboard', 'Paper and cardboard soiled by food go in the brown bin: pizza boxes, fry bags, muffin papers, parchment paper. Waxed, plastic-coated or laminated ones go in the garbage.', null, null), (@id, 'zh', '沾有食物的纸和纸板', '沾有食物的纸和纸板放入棕桶：披萨盒、薯条袋、松饼纸托、烘焙纸。打蜡、覆塑或覆膜的放入垃圾桶。', null, null);
