insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'waxed-or-laminated-paper', 'garbage', 'black', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Papier cire, plastifie ou lamine', 'Les papiers et cartons cires, plastifies ou lamines vont a la poubelle, comme ceux souilles d''un produit nettoyant nocif.', null, null), (@id, 'en', 'Waxed, plastic-coated or laminated paper', 'Waxed, plastic-coated or laminated paper and cardboard go in the garbage, as do any soiled with a harmful cleaning product.', null, null), (@id, 'zh', '打蜡、覆塑或覆膜的纸', '打蜡、覆塑或覆膜的纸和纸板放入垃圾桶，沾有有害清洁剂的纸也一样。', null, null);
