insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'yard-waste', 'organic', 'brown', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Residus verts', 'Plantes, feuilles, copeaux non traites, terre et terreau en petites quantites vont au bac brun. En avril, mai, octobre et novembre, les surplus sont ramasses a cote du bac: contenant marque d''un V, sac de papier ou boite de carton, 23 kg au plus. Jamais de sac de plastique.', null, null), (@id, 'en', 'Yard waste', 'Plants, leaves, untreated wood chips, and soil and potting soil in small amounts go in the brown bin. In April, May, October and November surplus is collected beside the bin: a container marked V, a paper bag or a cardboard box, 23 kg at most. Never plastic bags.', null, null), (@id, 'zh', '园林垃圾', '植物、落叶、未处理木屑以及少量泥土和盆栽土放入棕桶。4、5、10、11 月，桶旁多出的部分也会收走：请用标有 V 的容器、纸袋或纸箱，每件不超过 23 公斤。不收塑料袋。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'feuilles mortes'), (@id, 'fr', 1, 'gazon'), (@id, 'fr', 2, 'terreau'), (@id, 'en', 0, 'leaves'), (@id, 'en', 1, 'grass clippings'), (@id, 'en', 2, 'potting soil'), (@id, 'zh', 0, '落叶'), (@id, 'zh', 1, '草屑'), (@id, 'zh', 2, '盆栽土');
