insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'invasive-plants', 'garbage', 'black', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Plantes envahissantes', 'Les plantes envahissantes ne vont pas au bac brun: jetez-les aux ordures.', null, null), (@id, 'en', 'Invasive plants', 'Invasive plants do not go in the brown bin: put them in the garbage.', null, null), (@id, 'zh', '入侵植物', '入侵植物不要放入棕桶，请放入垃圾桶。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'renouee du Japon'), (@id, 'fr', 1, 'nerprun'), (@id, 'en', 0, 'Japanese knotweed'), (@id, 'en', 1, 'buckthorn'), (@id, 'zh', 0, '日本虎杖'), (@id, 'zh', 1, '鼠李');
