insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'branches', 'organic', 'brown', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Branches', 'Les branches de 30 cm et moins et de 4 cm de diametre ou moins vont au bac brun; coupez les longues branches minces. En 2026, la Ville a ramasse les branches plus grosses du 28 avril au 29 octobre, sur inscription (450 435-1954). Hors de cette periode, apportez-les a l''ecocentre (frais applicables).', null, null), (@id, 'en', 'Branches', 'Branches 30 cm or shorter and 4 cm across or less go in the brown bin; cut long thin ones. In 2026 the city collected larger branches from 28 April to 29 October, by registration (450 435-1954). Outside that period, take them to the ecocentre (fees apply).', null, null), (@id, 'zh', '树枝', '长度 30 厘米以内、直径 4 厘米以内的树枝放入棕桶；细长树枝请剪短。2026 年市政府于 4 月 28 日至 10 月 29 日登记收集较粗的树枝（450 435-1954）。其他时间请送到生态中心（收费）。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'petites branches'), (@id, 'en', 0, 'small branches'), (@id, 'zh', 0, '小树枝');
