insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Litiere et excrements d''animaux', 'A Boisbriand, la litiere, les excrements d''animaux domestiques et le fumier de poule vont au bac brun.', null, null), (@id, 'en', 'Pet litter and animal waste', 'In Boisbriand, pet litter, pet waste and chicken manure go in the brown bin.', null, null), (@id, 'zh', '猫砂和宠物粪便', '在 Boisbriand，猫砂、宠物粪便和鸡粪放入棕桶。', null, null);
