insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Cendres refroidies', 'Les cendres vont au bac brun si elles sont refroidies depuis plus de 72 heures.', null, null), (@id, 'en', 'Cooled ashes', 'Ashes go in the brown bin once they have been cold for more than 72 hours.', null, null), (@id, 'zh', '冷却的灰烬', '灰烬冷却超过 72 小时后可放入棕桶。', null, null);
