insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'compostable-or-biodegradable-dishes-and-bags', 'garbage', 'black', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Sacs de plastique, meme compostables', 'Aucun sac de plastique, meme transparent, biodegradable ou compostable, n''est accepte dans le bac brun ni dans les surplus de residus verts; les plastiques degradables ne vont pas non plus au bac de recuperation. Ils vont donc aux dechets. Utilisez un sac de papier.', null, null), (@id, 'en', 'Plastic bags, even compostable', 'No plastic bag, even clear, biodegradable or compostable, is accepted in the brown bin or with green-waste surplus; degradable plastics do not go in the recycling bin either. So they go in the garbage. Use a paper bag.', null, null), (@id, 'zh', '塑料袋（包括可堆肥袋）', '棕桶和园林垃圾都不收任何塑料袋，包括透明、可降解或可堆肥的；可降解塑料也不能放入回收桶。因此请放入垃圾桶，并改用纸袋。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'sac compostable'), (@id, 'fr', 1, 'sac biodegradable'), (@id, 'en', 0, 'compostable bag'), (@id, 'en', 1, 'biodegradable bag'), (@id, 'zh', 0, '可堆肥袋'), (@id, 'zh', 1, '可降解袋');
