insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'containers-and-packaging', 'recycling', 'blue', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Contenants, emballages et imprimes', 'Le bac de recuperation prend les contenants, les emballages et les imprimes. C''est tout. Videz et rincez legerement; retirez les couvercles des pots, sauf les petits bouchons; separez les matieres d''un emballage.', null, null), (@id, 'en', 'Containers, packaging and printed paper', 'The recycling bin takes containers, packaging and printed paper. That is all. Empty and lightly rinse; take lids off jars, except small caps; separate the materials of a package.', null, null), (@id, 'zh', '容器、包装和印刷品', '回收桶只收容器、包装和印刷品。请倒空并简单冲洗；取下罐子的盖子（小瓶盖除外）；把包装的不同材料分开。', null, null);
