insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Journaux, circulaires et papier', 'Les journaux, circulaires, enveloppes, feuilles et cahiers vont au bac de recuperation.', null, null), (@id, 'en', 'Newspapers, flyers and paper', 'Newspapers, flyers, envelopes, sheets of paper and notebooks go in the recycling bin.', null, null), (@id, 'zh', '报纸、传单和纸张', '报纸、传单、信封、纸张和笔记本放入回收桶。', null, null);
