insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'cardboard-boxes', 'recycling', 'blue', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Boites de carton', 'Defaites et pliees, les boites de carton vont au bac de recuperation. Les surplus de carton a cote du bac ne sont ramasses que lors de deux collectes speciales par annee (en 2026: 13 au 16 janvier, 7 au 10 juillet). Les tres grandes boites vont gratuitement a l''ecocentre.', null, null), (@id, 'en', 'Cardboard boxes', 'Broken down and flattened, cardboard boxes go in the recycling bin. Extra cardboard beside the bin is only taken at two special collections a year (in 2026: 13-16 January, 7-10 July). Very large boxes go to the ecocentre, free.', null, null), (@id, 'zh', '纸箱', '纸箱拆开压平后放入回收桶。桶旁多出的纸板每年只在两次特别收集时收走（2026 年：1 月 13-16 日、7 月 7-10 日）。很大的纸箱可免费送到生态中心。', null, null);
