insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'aluminium-cans-and-foil', 'recycling', 'blue', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Assiettes et papier d''aluminium', 'Les assiettes et le papier d''aluminium vont au bac de recuperation; faites une boulette du papier, meme legerement souille.', null, null), (@id, 'en', 'Aluminium plates and foil', 'Aluminium plates and foil go in the recycling bin; roll the foil into a ball, even if slightly soiled.', null, null), (@id, 'zh', '铝盘和铝箔', '铝盘和铝箔放入回收桶；铝箔即使略脏，也请揉成团。', null, null);
