insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'pots-and-pans', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Casseroles et poeles', 'Une casserole n''est ni un contenant ni un emballage: elle ne va pas au bac de recuperation. L''ecocentre accepte le metal.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Pots and pans', 'A pot is neither a container nor packaging: it does not go in the recycling bin. The ecocentre takes metal.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '锅具', '锅具既不是容器也不是包装，不能放入回收桶。生态中心接收金属。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
