insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'broken-toy', 'garbage', 'black', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Jouets, boyaux et chaises de jardin', 'Jouets, boyaux d''arrosage et chaises de jardin ne vont pas au bac de recuperation. Donnez-les s''ils servent encore; sinon, ce sont des dechets: le calendrier de la Ville definit le bac de dechets comme ce qui n''est ni recyclable, ni compostable, ni valorisable, ni dangereux.', null, null), (@id, 'en', 'Toys, garden hoses and garden chairs', 'Toys, garden hoses and garden chairs do not go in the recycling bin. Give them away if they still work; otherwise they are garbage: the city''s calendar defines the garbage bin as what is not recyclable, compostable, recoverable or hazardous.', null, null), (@id, 'zh', '玩具、水管和花园椅', '玩具、浇花水管和花园椅不能放入回收桶。还能用就送人；否则属于垃圾：市政府日历将垃圾桶定义为不可回收、不可堆肥、不可再利用、无危险的物品。', null, null);
