insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'clothing-and-textiles', 'special', 'none', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Vetements et tissus', 'Les vetements et les tissus ne vont pas au bac de recuperation. Donnez-les: les Fripes du Relais, 305 chemin de la Grande-Cote, les acceptent pendant les heures d''ouverture, ou dans la cloche de dons a droite de l''entree du IGA du Faubourg Boisbriand.', null, null), (@id, 'en', 'Clothing and textiles', 'Clothing and textiles do not go in the recycling bin. Donate them: Fripes du Relais, 305 chemin de la Grande-Cote, takes them during opening hours, or use the donation bin to the right of the IGA entrance at Faubourg Boisbriand.', null, null), (@id, 'zh', '衣物和纺织品', '衣物和纺织品不能放入回收桶。请捐赠：Fripes du Relais（305 chemin de la Grande-Cote）营业时间接收，或投入 Faubourg Boisbriand 的 IGA 入口右侧的捐赠箱。', null, null);
