insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'household-waste', 'garbage', 'black', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Dechets', 'Le bac de dechets est pour ce qui n''est ni recyclable, ni compostable, ni valorisable, ni dangereux, et qui est en fin de vie. Il est ramasse aux deux semaines; 250 lb au plus.', null, null), (@id, 'en', 'Garbage', 'The garbage bin is for what is not recyclable, compostable, recoverable or hazardous, and has reached the end of its life. It is collected every two weeks; 250 lb at most.', null, null), (@id, 'zh', '生活垃圾', '垃圾桶用于不可回收、不可堆肥、不可再利用、无危险且已无用的物品。每两周收一次，重量不超过 250 磅。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'dechets'), (@id, 'fr', 1, 'poubelle'), (@id, 'en', 0, 'trash'), (@id, 'en', 1, 'garbage'), (@id, 'zh', 0, '垃圾');
