insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'bulky-items', 'bulky', 'none', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Dechets excedentaires et meubles', 'Une fois par mois, le jour habituel de votre collecte, les dechets qui n''entrent pas dans le bac sont ramasses: meubles, petits electromenagers sans halocarbures, materiaux de construction sans clous, ensaches ou attaches, 23 kg par paquet, 5 m3 par adresse. En 2026, la derniere est du 15 au 18 decembre. Refuses: gros electromenagers et appareils refrigerants, electroniques, pneus, residus dangereux, troncs et souches. Un meuble encore bon: le Grenier populaire le ramasse a domicile.', null, 'Une fois par mois, le jour habituel de votre collecte. En bordure de la chaussee des 18 h la veille ou avant 7 h le jour meme.'), (@id, 'en', 'Excess waste and furniture', 'Once a month, on your usual collection day, waste that does not fit in the bin is collected: furniture, small appliances without halocarbons, nail-free building materials, bagged or tied, 23 kg a bundle, 5 m3 per address. In 2026 the last one is 15-18 December. Refused: large and refrigerating appliances, electronics, tires, hazardous waste, trunks and stumps. Furniture still in good shape: Grenier populaire picks it up from your home.', null, 'Once a month, on your usual collection day. At the curb from 6 p.m. the day before or by 7 a.m. that day.'), (@id, 'zh', '超量垃圾和家具', '每月一次，在您平常的收运日收取放不进垃圾桶的物品：家具、不含卤烃的小家电、无钉建材，需装袋或捆扎，每捆 23 公斤以内，每个地址最多 5 立方米。2026 年最后一次是 12 月 15-18 日。不收：大型家电和制冷电器、电子产品、轮胎、危险废物、树干和树桩。还能用的家具可由 Grenier populaire 上门收取。', null, '每月一次，在您平常的收运日。前一天 18 点后或当天 7 点前放到路边。');
