insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'refrigerating-appliances', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Electromenagers et appareils refrigerants', 'Les gros electromenagers et les appareils refrigerants ne sont pas ramasses avec les dechets excedentaires. Apportez-les a l''ecocentre, ou faites-les ramasser par le Grenier populaire, fonctionnels ou non.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Large and refrigerating appliances', 'Large and refrigerating appliances are not taken with excess waste. Take them to the ecocentre, or have Grenier populaire pick them up, working or not.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '大型家电和制冷电器', '大型家电和制冷电器不随超量垃圾收集。请送到生态中心，或请 Grenier populaire 上门收取（无论能否使用）。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
