insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'paint', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Peinture, solvants et produits dangereux', 'La peinture, les solvants et les autres residus dangereux ne vont dans aucun bac: apportez-les a l''ecocentre.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Paint, solvents and hazardous products', 'Paint, solvents and other hazardous waste go in no bin: take them to the ecocentre.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '油漆、溶剂和危险品', '油漆、溶剂和其他危险废物不能放入任何垃圾桶，请送到生态中心。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
