insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'tires', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Pneus', 'Les pneus ne sont pas ramasses; apportez-les a l''ecocentre, sans jante.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Tires', 'Tires are not collected; take them to the ecocentre, off the rim.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '轮胎', '轮胎不在收运范围，请拆下轮毂后送到生态中心。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
