insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'construction-debris', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Materiaux de construction', 'De petites quantites de materiaux sans clous, attaches en paquets de 23 kg ou moins, partent avec les dechets excedentaires. Avec des clous, trop lourds ou en grande quantite, ils vont a l''ecocentre; la Ville prete gratuitement une remorque pour les y apporter.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Construction materials', 'Small amounts of nail-free materials, tied in bundles of 23 kg or less, go with excess waste. With nails, too heavy or in quantity, they go to the ecocentre; the city lends a trailer for free to take them there.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '建筑材料', '少量无钉建材捆成每捆 23 公斤以内，可随超量垃圾收走。带钉、过重或量大的请送到生态中心；市政府免费出借拖车用于运送。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
