insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'stumps-and-logs', 'ecocentre', 'none', 'https://www.sainte-therese.ca/services/services-aux-citoyens/ecocentre');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Souches, troncs et bois traite', 'Les buches, les souches, les troncs et le bois traite, peint ou teint vont a l''ecocentre (frais applicables), pas au bac brun.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence de Boisbriand exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (@id, 'en', 'Stumps, logs and treated wood', 'Logs, stumps, trunks and treated, painted or stained wood go to the ecocentre (fees apply), not the brown bin.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of Boisbriand residence required. Closed from 21 December 2026 to 7 January 2027.'), (@id, 'zh', '树桩、原木和处理过的木材', '原木、树桩、树干以及处理过、涂漆或染色的木材请送到生态中心（收费），不要放入棕桶。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示 Boisbriand 居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
