insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'cedar-trimmings', 'special', 'none', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Retailles de cedre', 'Du 1er mai au 31 octobre, la collecte des retailles de cedre est gratuite sur inscription en ligne (arbressence.ca). En tout temps, elles peuvent aussi aller au bac brun.', null, null), (@id, 'en', 'Cedar trimmings', 'From 1 May to 31 October, cedar trimmings are collected free by online registration (arbressence.ca). They can also go in the brown bin at any time.', null, null), (@id, 'zh', '雪松修剪枝叶', '5 月 1 日至 10 月 31 日，可在网上登记（arbressence.ca）免费收集雪松修剪枝叶。任何时候也可放入棕桶。', null, null);
