insert into sorting_item (municipality_id, item_key, destination_type, bin_color, source_url) values (@bb, 'christmas-trees', 'special', 'none', 'https://www.ville.boisbriand.qc.ca/services/citoyens/collectes-des-matieres-residuelles');
insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (@id, 'fr', 'Sapins de Noel', 'Les sapins naturels sont ramasses lors d''une collecte en janvier (le 14 janvier en 2026), sans inscription: a l''horizontale pres de la rue, sans decoration, ni attache ni sac. Hors collecte: avec les branches ou a l''ecocentre.', null, null), (@id, 'en', 'Christmas trees', 'Real trees are picked up in one January collection (14 January in 2026), no registration: lying near the street, undecorated, not tied or bagged. Otherwise: with branch pickup or at the ecocentre.', null, null), (@id, 'zh', '圣诞树', '天然圣诞树在一月的一次收集中收走（2026 年是 1 月 14 日），无需登记：横放在路边，去掉装饰，不要捆绑或装袋。其他时间可随树枝收集或送到生态中心。', null, null);
insert into sorting_item_example (item_id, language_code, position, example) values (@id, 'fr', 0, 'sapin naturel'), (@id, 'en', 0, 'real Christmas tree'), (@id, 'zh', 0, '真圣诞树');
